# Writer agent UUID (second one scaffolded)
WRITER_UUID = "e3cf0113-f230-4009-abe6-68c7b956534e"

# Load current flow (has CLI-owned nodes + bindings)
flow = json.load(open("BillingDisputeResolution.flow"))

# Load definitions from registry
agent_def = json.load(open("/tmp/agent_autonomous.json"))["Data"]["Node"]
context_def = json.load(open("/tmp/context_node.json"))["Data"]["Node"]
api_wf_def = json.load(open("/tmp/api_workflow.json"))["Data"]["Node"]
end_def = json.load(open("/tmp/end_node.json"))["Data"]["Node"]
switch_def = json.load(open("/tmp/switch_node.json"))["Data"]["Node"]
decision_def = json.load(open("/tmp/decision_node.json"))["Data"]["Node"]
merge_def = json.load(open("/tmp/merge_node.json"))["Data"]["Node"]
script_def = json.load(open("/tmp/script_node.json"))["Data"]["Node"]
ixp_def = json.load(open("/tmp/ixp_node.json"))["Data"]["Node"]
ixp_defaults = ixp_def["inputDefaults"]
ixp_outdef = ixp_def["outputDefinition"]

# Keep CLI-owned nodes (crmLookup1 renamed to crmLookup, erpLookup1 kept, remove crmLookup2)
# The node IDs from CLI: crmLookup1=CRM, erpLookup1=ERP, crmLookup2=extra (remove it)
# But there's an extra crmLookup2 we don't need - remove it from the nodes list
existing_nodes = {n["id"]: n for n in flow["nodes"]}

# Keep: start, crmLookup1 (rename display to CRM Lookup), erpLookup1 (ERP Lookup)
# Remove: crmLookup2 (duplicate)
start_node = existing_nodes["start"]
crm_node = existing_nodes["crmLookup1"]
crm_node["display"]["label"] = "CRM Lookup"
erp_node = existing_nodes["erpLookup1"]

# IxP node
ixp_node = {
    "id": "extractInvoice",
    "type": "uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178",
    "typeVersion": "1.0.0",
    "display": {"label": "Invoice Extraction (IxP)"},
    "inputs": {
        "model": {
            "id": ixp_defaults["model"]["id"],
            "modelName": ixp_defaults["model"]["modelName"],
            "modelDisplayName": ixp_defaults["model"]["modelDisplayName"],
            "folderKey": ixp_defaults["model"]["folderKey"],
            "folderName": ixp_defaults["model"]["folderName"],
            "folderPath": ixp_defaults["model"]["folderPath"],
            "description": ixp_defaults["model"].get("description", "")
        },
        "modelName": ixp_defaults["modelName"],
        "projectName": ixp_defaults["projectName"],
        "folderKey": ixp_defaults["folderKey"],
        "folderName": ixp_defaults["folderName"],
        "versionTag": "",
        "pageRange": "",
        "fileRef": "=js:$vars.start.output.disputedInvoice"
    },
    "outputs": {
        "output": ixp_outdef["output"],
        "error": ixp_outdef["error"]
    }
}

# Normalize Data script node
normalize_node = {
    "id": "normalizeData",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Normalize Data"},
    "inputs": {
        "script": """var fields = ($vars.extractInvoice.output.ExtractionResult || {}).ResultsDocument && $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields || [];
var normalized = fields.map(function(f) {
  return { Id: f.FieldId, Name: f.FieldName, Value: f.Values && f.Values[0] || null, Type: f.FieldType, IsMissing: f.IsMissing, Confidence: f.Confidence };
});
return { fields: normalized };"""
    },
    "outputs": {
        "output": {"type": "object", "description": "Normalized fields array", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error information if the script fails", "source": "=result.Error", "var": "error"}
    }
}

# Merge node (after parallel CRM + ERP)
merge_node = {
    "id": "mergeResults",
    "type": "core.logic.merge",
    "typeVersion": "1.0",
    "display": {"label": "Merge CRM + ERP"},
    "inputs": {}
}

# Discrepancy Detection script
discrepancy_node = {
    "id": "detectDiscrepancy",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Discrepancy Detection"},
    "inputs": {
        "script": """var disputedItems = ($vars.start.output.webhookPayload || {}).dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems || [];
var erpRecords = ($vars.erpLookup1.output || {}).Records || ($vars.erpLookup1.output || {}).Value || [];
var lineDiscrepancies = [];
var totalOvercharge = 0;
var totalUndercharge = 0;
disputedItems.forEach(function(item) {
  var contractRow = erpRecords.find(function(r) { return r.lineNumber == item.lineNumber; });
  if (contractRow) {
    var contractAmount = contractRow.amount || (contractRow.quantity * contractRow.unitPrice) || 0;
    var diff = item.amount - contractAmount;
    if (diff > 0) { totalOvercharge += diff; }
    else if (diff < 0) { totalUndercharge += Math.abs(diff); }
    lineDiscrepancies.push({ lineNumber: item.lineNumber, disputedAmount: item.amount, contractAmount: contractAmount, difference: diff, description: item.description });
  }
});
return { lineDiscrepancies: lineDiscrepancies, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge, hasDiscrepancy: lineDiscrepancies.length > 0 };"""
    },
